// @ts-ignore -- generated by opennextjs-cloudflare build; absent before the first build
import handler from './.open-next/worker.js'
import { edgeCacheKey, isEdgeCacheableRequest, isEdgeCacheableResponse } from './src/lib/edge-cache'

// @ts-ignore -- generated by opennextjs-cloudflare build; absent before the first build
export { DOQueueHandler } from './.open-next/worker.js'

type Ctx = { waitUntil(promise: Promise<unknown>): void }
type Env = { ADMIN_HOST?: string }
type Next = { fetch(req: Request, env: unknown, ctx: Ctx): Promise<Response> }

const next = handler as Next
const edge = (caches as unknown as { default: Cache }).default

function tagged(res: Response, value: 'HIT' | 'MISS'): Response {
  const out = new Response(res.body, res)
  out.headers.set('x-edge-cache', value)
  return out
}

export default {
  async fetch(req: Request, env: Env, ctx: Ctx): Promise<Response> {
    if (!isEdgeCacheableRequest(req, env.ADMIN_HOST)) return next.fetch(req, env, ctx)
    const key = edgeCacheKey(req)
    const range = req.headers.get('range')
    // A cached 200 answers a Range request with a 206, so video previews hit too.
    const lookup = new Request(key, range ? { headers: { range } } : undefined)
    const hit = await edge.match(lookup).catch(() => undefined)
    if (hit) return tagged(hit, 'HIT')
    const res = await next.fetch(req, env, ctx)
    if (isEdgeCacheableResponse(res)) {
      ctx.waitUntil(edge.put(key, res.clone()).catch(() => undefined))
    }
    return tagged(res, 'MISS')
  },
}
